import { Program } from '../types';

// Generate SEO-friendly URL slugs from program data
export function generateProgramSlug(program: Program): string {
  const universityShort = program.university.includes('Jaipur') ? 'manipal-jaipur' : 'sikkim-manipal';
  const programName = program.title.toLowerCase().replace(/\s+/g, '-');
  return `online-${programName}-${universityShort}`;
}

// Generate program-specific SEO slugs with special handling
export function generateDetailedSlug(program: Program): string {
  const universityShort = program.university.includes('Jaipur') ? 'manipal-jaipur' : 'sikkim-manipal';
  
  // Handle special cases like MA-JMC, MA Economics, etc.
  let detailedName;
  if (program.id === 'majmc-muj') {
    detailedName = 'ma-journalism-mass-communication';
  } else if (program.id === 'ma-eco-muj') {
    detailedName = 'ma-economics';
  } else if (program.id === 'msc-math-muj') {
    detailedName = 'msc-mathematics';
  } else if (program.id === 'ma-pol-smu') {
    detailedName = 'ma-political-science';
  } else if (program.id === 'ma-eng-smu') {
    detailedName = 'ma-english';
  } else if (program.id === 'ma-soc-smu') {
    detailedName = 'ma-sociology';
  } else {
    detailedName = program.fullName.toLowerCase().replace(/\s+/g, '-');
  }
    
  return `online-${detailedName}-${universityShort}`;
}

// Generate SEO-friendly program URL
export function generateProgramUrl(program: Program): string {
  return `/programs/${generateProgramSlug(program)}`;
}

// Parse program ID from SEO-friendly slug
export function parseProgramSlug(slug: string): string {
  // Remove 'online-' prefix and university suffix
  const parts = slug.replace('online-', '').split('-');
  
  // Get program abbreviation
  const programAbbreviation = parts[0].toUpperCase();
  
  // Get university suffix
  const universitySuffix = slug.includes('manipal-jaipur') ? 'muj' : 'smu';
  
  return `${programAbbreviation}-${universitySuffix}`;
}

// Generate breadcrumb items for schema
export function generateBreadcrumbItems(program?: Program) {
  const baseUrl = 'https://onlinemanipal.com';
  
  if (!program) {
    return [
      {
        "@type": "ListItem",
        "position": 1,
        "name": "Home",
        "item": baseUrl
      }
    ];
  }

  const slug = generateProgramSlug(program);
  const universityShort = program.university.includes('Jaipur') ? 'MUJ' : 'SMU';

  return [
    {
      "@type": "ListItem",
      "position": 1,
      "name": "Home",
      "item": baseUrl
    },
    {
      "@type": "ListItem",
      "position": 2,
      "name": "Online Programs",
      "item": `${baseUrl}/#programs-section`
    },
    {
      "@type": "ListItem",
      "position": 3,
      "name": `${program.title} - ${universityShort}`,
      "item": `${baseUrl}/programs/${slug}`
    }
  ];
}

// Create a mapping of SEO slugs to program IDs
export function createSlugMapping(programs: Program[]): Map<string, string> {
  const mapping = new Map<string, string>();
  
  programs.forEach(program => {
    const slug = generateProgramSlug(program);
    mapping.set(slug, program.id);
  });
  
  return mapping;
}

// Get program by SEO slug
export function getProgramBySlug(slug: string, programs: Program[]): Program | undefined {
  // Try exact match first
  const mapping = createSlugMapping(programs);
  const programId = mapping.get(slug);
  if (programId) {
    return programs.find(p => p.id === programId);
  }
  
  // Try to match partial slug for flexibility
  const slugLower = slug.toLowerCase();
  return programs.find(program => {
    const programSlug = generateProgramSlug(program);
    const detailedSlug = generateDetailedSlug(program);
    return programSlug === slugLower || 
           detailedSlug === slugLower ||
           slugLower.includes(programSlug) || 
           programSlug.includes(slugLower) ||
           slugLower.includes(detailedSlug) ||
           detailedSlug.includes(slugLower);
  });
}